-- Umbral: ejecutar en Supabase > SQL Editor
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null default 'Lector',created_at timestamptz not null default now());
create table if not exists public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
create table if not exists public.stories(id uuid primary key default gen_random_uuid(),author_id uuid references auth.users(id) on delete set null,author_name text not null default 'Anónimo',title text not null check(char_length(title) between 5 and 120),summary text check(summary is null or char_length(summary)<=280),body text not null check(char_length(body) between 80 and 20000),category text not null default 'Experiencia personal' check(category in('Paranormal','Experiencia personal','Ficción','Leyenda urbana','Críptidos','Otro')),status text not null default 'pending' check(status in('pending','published','rejected','changes','draft')),consent boolean not null default false,moderation_note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),published_at timestamptz);
create table if not exists public.videos(id uuid primary key default gen_random_uuid(),title text not null,description text,youtube_url text not null,story_id uuid references public.stories(id) on delete set null,is_published boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.story_likes(id uuid primary key default gen_random_uuid(),story_id uuid not null references public.stories(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),unique(story_id,user_id));
create table if not exists public.video_likes(id uuid primary key default gen_random_uuid(),video_id uuid not null references public.videos(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),unique(video_id,user_id));
create index if not exists stories_status_date_idx on public.stories(status,published_at desc);create index if not exists stories_author_idx on public.stories(author_id,created_at desc);
create or replace function public.is_umbral_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())); $$;
revoke all on function public.is_umbral_admin() from public;grant execute on function public.is_umbral_admin() to authenticated;
alter table public.profiles enable row level security;alter table public.admin_users enable row level security;alter table public.stories enable row level security;alter table public.videos enable row level security;alter table public.story_likes enable row level security;alter table public.video_likes enable row level security;
revoke all on public.profiles,public.admin_users,public.stories,public.videos,public.story_likes,public.video_likes from anon,authenticated;
grant select,insert,update on public.profiles to authenticated;grant select on public.admin_users to authenticated;grant select,insert,update on public.stories to authenticated;grant select,insert on public.stories to anon;grant select on public.videos to anon,authenticated;grant select,insert,delete on public.story_likes,public.video_likes to authenticated;
create policy profiles_self on public.profiles for select to authenticated using(id=(select auth.uid()) or public.is_umbral_admin());create policy profiles_insert on public.profiles for insert to authenticated with check(id=(select auth.uid()));create policy profiles_update on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy admin_self on public.admin_users for select to authenticated using(user_id=(select auth.uid()));
create policy stories_read on public.stories for select to anon,authenticated using(status='published' or author_id=(select auth.uid()) or public.is_umbral_admin());
create policy stories_anon_insert on public.stories for insert to anon with check(author_id is null and status='pending' and consent=true and char_length(title) between 5 and 120 and char_length(body) between 80 and 20000);
create policy stories_user_insert on public.stories for insert to authenticated with check((author_id=(select auth.uid()) or author_id is null) and status='pending' and consent=true);
create policy stories_owner_update on public.stories for update to authenticated using(author_id=(select auth.uid()) and status in('pending','changes','draft')) with check(author_id=(select auth.uid()) and status in('pending','changes','draft'));
create policy stories_admin_update on public.stories for update to authenticated using(public.is_umbral_admin()) with check(public.is_umbral_admin());
create policy videos_read on public.videos for select to anon,authenticated using(is_published=true or public.is_umbral_admin());create policy videos_admin_insert on public.videos for insert to authenticated with check(public.is_umbral_admin());create policy videos_admin_update on public.videos for update to authenticated using(public.is_umbral_admin()) with check(public.is_umbral_admin());create policy videos_admin_delete on public.videos for delete to authenticated using(public.is_umbral_admin());
create policy story_likes_read on public.story_likes for select to authenticated using(true);create policy story_likes_insert on public.story_likes for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.stories s where s.id=story_id and s.status='published'));create policy story_likes_delete on public.story_likes for delete to authenticated using(user_id=(select auth.uid()));
create policy video_likes_read on public.video_likes for select to authenticated using(true);create policy video_likes_insert on public.video_likes for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.videos v where v.id=video_id and v.is_published=true));create policy video_likes_delete on public.video_likes for delete to authenticated using(user_id=(select auth.uid()));
create or replace function public.moderate_story(p_story_id uuid,p_new_status text,p_moderation_note text default null) returns void language plpgsql security invoker set search_path='' as $$ begin if not public.is_umbral_admin() then raise exception 'No autorizado'; end if; if p_new_status not in('published','rejected','changes') then raise exception 'Estado inválido'; end if; update public.stories set status=p_new_status,moderation_note=left(p_moderation_note,1000),updated_at=now(),published_at=case when p_new_status='published' then now() else null end where id=p_story_id; if not found then raise exception 'Historia no encontrada'; end if; end; $$;
revoke all on function public.moderate_story(uuid,text,text) from public,anon;grant execute on function public.moderate_story(uuid,text,text) to authenticated;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(nullif(new.raw_user_meta_data->>'display_name',''),'Lector')) on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
-- Tras registrarte, usa el UUID que devuelve esta consulta y asígnate el rol admin:
-- select id,email from auth.users where email='TU_CORREO';
-- insert into public.admin_users(user_id) values ('UUID_DE_TU_USUARIO');

-- Contadores públicos: solo devuelven un número, no exponen la identidad de quienes dieron like.
create or replace function public.story_like_count(p_story_id uuid) returns bigint language sql stable security definer set search_path='' as $$ select count(*) from public.story_likes l join public.stories s on s.id=l.story_id where l.story_id=p_story_id and s.status='published'; $$;
create or replace function public.video_like_count(p_video_id uuid) returns bigint language sql stable security definer set search_path='' as $$ select count(*) from public.video_likes l join public.videos v on v.id=l.video_id where l.video_id=p_video_id and v.is_published=true; $$;
revoke all on function public.story_like_count(uuid) from public; revoke all on function public.video_like_count(uuid) from public; grant execute on function public.story_like_count(uuid) to anon,authenticated; grant execute on function public.video_like_count(uuid) to anon,authenticated;
